def chart_layout(height=340):
    return dict(paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(255,255,255,0.03)",
        font=dict(family="DM Sans", color=TXT, size=11), height=height,
        margin=dict(l=40,r=20,t=30,b=40),
        xaxis=dict(gridcolor="rgba(118,120,237,0.15)", linecolor="rgba(255,255,255,0.1)", tickfont=dict(color=TXT2)),
        yaxis=dict(gridcolor="rgba(118,120,237,0.15)", linecolor="rgba(255,255,255,0.1)", tickfont=dict(color=TXT2)),
        colorway=PALETTE, showlegend=True,
        legend=dict(bgcolor="rgba(0,0,0,0)", font=dict(color=TXT, size=10)))

@st.cache_data
def load_data():
    df = pd.read_csv("sdg4_cleaned.csv")
    df["log_gdp"] = np.log(df["gdp_per_capita"])
    return df

