pn = prev_year_data["internet_usage_pct"].mean() if not prev_year_data.empty else cn
cg = df_year["gdp_per_capita"].mean()
cv = df_year["gov_edu_spending_pct"].mean()
top_c = df_year.loc[df_year["avg_years_schooling"].idxmax(),"Entity"]

