    trend_insight = f"📌 Global average schooling rose from <strong>{ys['mean'].iloc[0]:.2f} years</strong> in 2000 to <strong>{ys['mean'].iloc[-1]:.2f} years</strong> in 2023 — a steady upward trend, though significant gaps between rich and poor countries persist."
